// ==== VORLTEX TEK DOSYA SUNUCU ====
// Çalıştır:  node server.js   (ws kütüphanesi yoksa kendisi kurar)
// Oyun, gizlilik sayfası ve online sunucu hepsi bu dosyada.
//   /            -> oyun        /privacy.html -> gizlilik politikası
// Ortam değişkenleri: PORT, GOOGLE_CLIENT_ID (Google girişi), BANNED_EMAILS
const zlib = require("zlib");
try { require.resolve("ws"); } catch (e) {
  console.log("ws kuruluyor...");
  require("child_process").execSync("npm install ws --no-save --no-audit --no-fund", { stdio: "inherit", cwd: __dirname });
}
const GAME_GZ = "";
const PRIV_GZ = "";
const GAME = zlib.gunzipSync(Buffer.from(GAME_GZ, "base64")).toString("utf8");
const PRIV = zlib.gunzipSync(Buffer.from(PRIV_GZ, "base64")).toString("utf8");
// VORLTEX online sunucusu: oyuncuları odalarda buluşturur, konum/vuruş/sohbet mesajlarını iletir.
const http = require("http");
const https = require("https");
const { WebSocketServer } = require("ws");

const PORT = process.env.PORT || 8787;
const MAX_CLIENTS = 300;      // aynı anda en fazla oyuncu
const MAX_MSG = 2048;         // bir mesajın en büyük boyutu (bayt)
const RATE = 80;              // bir oyuncunun saniyedeki en fazla mesajı
const TICK = 100;             // oyuncu listesi yayın aralığı (ms)

// --- Google giriş doğrulaması ---
// GOOGLE_CLIENT_ID verilirse, oyuncular Google ID token'ı ile doğrulanmadan odalara giremez.
const GOOGLE_CLIENT_ID = process.env.GOOGLE_CLIENT_ID || "";
const TOKENINFO_URL = process.env.TOKENINFO_URL || "https://oauth2.googleapis.com/tokeninfo";
const BANNED = new Set((process.env.BANNED_EMAILS || "").toLowerCase().split(",").map(s => s.trim()).filter(Boolean));
const REQUIRE_AUTH = !!GOOGLE_CLIENT_ID;
const tokCache = new Map(); // token -> {email, exp}

function verifyToken(token) {
  return new Promise((resolve) => {
    token = String(token || "");
    if (token.length < 20 || token.length > 3000) return resolve(null);
    const hit = tokCache.get(token);
    if (hit && hit.exp * 1000 > Date.now()) return resolve(hit);
    const u = new URL(TOKENINFO_URL); u.searchParams.set("id_token", token);
    const lib = u.protocol === "http:" ? http : https;
    const req = lib.get(u, { timeout: 6000 }, (res) => {
      let body = ""; res.on("data", (d) => { body += d; if (body.length > 8000) req.destroy(); });
      res.on("end", () => {
        try {
          const j = JSON.parse(body);
          const ok = res.statusCode === 200 && j.aud === GOOGLE_CLIENT_ID &&
            /^(https:\/\/)?accounts\.google\.com$/.test(j.iss || "") &&
            (j.email_verified === true || j.email_verified === "true") &&
            /^[a-z0-9._%+-]{3,}@gmail\.com$/i.test(j.email || "") && Number(j.exp) * 1000 > Date.now();
          if (!ok) return resolve(null);
          const r = { email: j.email.toLowerCase(), exp: Number(j.exp) };
          tokCache.set(token, r); if (tokCache.size > 2000) tokCache.clear();
          resolve(r);
        } catch (e) { resolve(null); }
      });
    });
    req.on("error", () => resolve(null)); req.on("timeout", () => { req.destroy(); resolve(null); });
  });
}

const server = http.createServer((req, res) => {
  const u = (req.url || "/").split("?")[0];
  if (u === "/" || u === "/index.html") { res.writeHead(200, { "content-type": "text/html; charset=utf-8" }); return res.end(GAME.replace("@@GCID@@", process.env.GOOGLE_CLIENT_ID || "")); }
  if (u === "/privacy.html") { res.writeHead(200, { "content-type": "text/html; charset=utf-8" }); return res.end(PRIV); }
  res.writeHead(200, { "content-type": "text/plain; charset=utf-8", "access-control-allow-origin": "*" });
  res.end("VORLTEX sunucusu çalışıyor. Oyuncu: " + clients.size + (REQUIRE_AUTH ? " · Google doğrulaması AÇIK" : " · Google doğrulaması KAPALI") + "\n");
});
const wss = new WebSocketServer({ server, maxPayload: MAX_MSG });
const clients = new Map(); // id -> {ws, presence, n, t}
let dirty = false;

const rid = () => Math.random().toString(36).slice(2, 10);
const clean = (v, n) => String(v == null ? "" : v).replace(/[<>]/g, "").slice(0, n);

function sanitizePresence(p) {
  if (!p || typeof p !== "object") return {};
  const o = {};
  for (const k of ["sel", "rm", "tm", "ag", "hc", "hm", "hmap"]) if (p[k] != null) o[k] = clean(p[k], 40);
  o.n = clean(p.n, 16);
  for (const k of ["x", "z", "yw"]) if (typeof p[k] === "number" && isFinite(p[k])) o[k] = Math.max(-500, Math.min(500, p[k]));
  if (p.al === 0 || p.al === 1) o.al = p.al;
  return o;
}
function sanitizeData(d) {
  if (!d || typeof d !== "object") return {};
  const o = {};
  for (const k in d) {
    const v = d[k];
    if (typeof v === "number" && isFinite(v)) o[k] = v;
    else if (typeof v === "string") o[k] = clean(v, 200);
  }
  return o;
}
function send(ws, obj) { if (ws.readyState === 1) ws.send(JSON.stringify(obj)); }

wss.on("connection", (ws) => {
  if (clients.size >= MAX_CLIENTS) { send(ws, { t: "full" }); ws.close(); return; }
  const id = rid();
  const c = { ws, presence: {}, cnt: 0, win: Date.now(), alive: true, authed: !REQUIRE_AUTH, email: null };
  clients.set(id, c);
  send(ws, { t: "hello", id, auth: REQUIRE_AUTH });
  if (REQUIRE_AUTH) setTimeout(() => { if (!c.authed) { try { ws.close(); } catch (e) {} } }, 15000);
  dirty = true;
  ws.on("pong", () => { c.alive = true; });
  ws.on("message", (raw) => {
    const now = Date.now();
    if (now - c.win > 1000) { c.win = now; c.cnt = 0; }
    if (++c.cnt > RATE) return;
    let m; try { m = JSON.parse(raw); } catch (e) { return; }
    if (!m || typeof m !== "object") return;
    if (m.t === "auth") {
      if (!REQUIRE_AUTH || c.verifying) return;
      c.verifying = true;
      verifyToken(m.token).then((r) => {
        c.verifying = false;
        if (!r) { send(ws, { t: "autherr", msg: "Google girişi doğrulanamadı. Çıkış yapıp tekrar giriş yap." }); return; }
        if (BANNED.has(r.email)) { send(ws, { t: "autherr", msg: "Bu hesap engellendi." }); try { ws.close(); } catch (e) {} return; }
        // aynı hesap ikinci kez bağlanırsa eskisini at (tek hesap = tek oturum)
        for (const [oid, o] of clients) if (oid !== id && o.email === r.email) { send(o.ws, { t: "kicked" }); try { o.ws.close(); } catch (e) {} clients.delete(oid); }
        c.email = r.email; c.authed = true; send(ws, { t: "authok" }); dirty = true;
      });
      return;
    }
    if (!c.authed) return;
    if (m.t === "pres") { c.presence = sanitizePresence(m.p); dirty = true; }
    else if (m.t === "emit") {
      const topic = clean(m.topic, 12);
      if (!["hit", "kill", "chat"].includes(topic)) return;
      const data = sanitizeData(m.data);
      if (topic === "hit" || topic === "kill") {
        // hedefe doğrudan ilet
        const target = clients.get(data.to);
        if (target) send(target.ws, { t: "msg", topic, data: Object.assign({}, data, { from: id }), from: id });
      } else {
        const room = c.presence.rm;
        for (const [, o] of clients) if (o.presence.rm === room) send(o.ws, { t: "msg", topic, data, from: id });
      }
    }
  });
  ws.on("close", () => { clients.delete(id); dirty = true; });
  ws.on("error", () => {});
});

// Her oyuncuya: kendi odasındakilerin tüm bilgisi, diğerlerinin sadece menü bilgisi
setInterval(() => {
  if (!dirty) return;
  dirty = false;
  const list = [...clients.entries()];
  for (const [id, c] of list) {
    const rm = c.presence.rm;
    const peers = list.map(([pid, o]) => {
      const p = o.presence;
      if (rm && p.rm === rm) return { peer: pid, presence: p };
      return { peer: pid, presence: { sel: p.sel, rm: p.rm, hc: p.hc, hm: p.hm, hmap: p.hmap } };
    });
    send(c.ws, { t: "peers", peers });
  }
}, TICK);
// Konum değişiklikleri sürekli geldiği için odadakiler her zaman yayınlanır
setInterval(() => { dirty = true; }, 250);

// Kopan bağlantıları temizle
setInterval(() => {
  for (const [id, c] of clients) {
    if (!c.alive) { try { c.ws.terminate(); } catch (e) {} clients.delete(id); dirty = true; continue; }
    c.alive = false; try { c.ws.ping(); } catch (e) {}
  }
}, 20000);

server.listen(PORT, () => console.log("VORLTEX sunucusu " + PORT + " portunda" + (REQUIRE_AUTH ? " (Google doğrulaması açık)" : " (UYARI: GOOGLE_CLIENT_ID yok, doğrulama kapalı)")));
